type Lang = "en" | "ar";
type Page = "dashboard" | "portal" | "approvals" | "employees" | "leave" | "attendance" | "org" | "users" | "settings";
type RoleId = "hr_manager" | "direct_manager" | "employee" | "super_admin";

const localeFor = (rtl: boolean) => rtl ? "ar-SA-u-nu-arab" : "en-GB";
const formatNumber = (value: number, rtl: boolean) => new Intl.NumberFormat(localeFor(rtl)).format(value);
const formatDate = (value: string | Date, rtl: boolean, options: Intl.DateTimeFormatOptions = { day:"numeric", month:"short", year:"numeric" }) =>
  new Intl.DateTimeFormat(localeFor(rtl), options).format(typeof value === "string" ? new Date(`${value}T12:00:00`) : value);
const formatTime = (value: string, rtl: boolean) => {
  const [hour,minute] = value.split(":").map(Number);
  return new Intl.DateTimeFormat(localeFor(rtl), { hour:"numeric", minute:"2-digit" }).format(new Date(2026,7,14,hour,minute));
};
const localizedStatus = (value: unknown, rtl: boolean) => {
  const key = String(value || "active").toLowerCase().replaceAll("_"," ");
  const ar:Record<string,string> = { active:"نشط", archived:"مؤرشف", "on leave":"في إجازة", probation:"تحت التجربة", suspended:"موقوف", "notice period":"فترة إشعار", pending:"قيد الانتظار", waiting:"بانتظار الإجراء", approved:"معتمد", rejected:"مرفوض", present:"حاضر", leave:"إجازة", late:"متأخر", configured:"مُعدّ", standard:"قياسي" };
  return rtl ? (ar[key] || String(value)) : key.replace(/\b\w/g, letter => letter.toUpperCase());
};
const localizedRequestType = (value: unknown, rtl: boolean) => {
  const key = String(value || "");
  const ar:Record<string,string> = { "Annual leave":"إجازة سنوية", "Sick leave":"إجازة مرضية", "Late arrival":"تأخر عن الدوام", "Early departure":"انصراف مبكر", "Work from home":"عمل عن بُعد", "Expense reimbursement":"استرداد مصروفات", "Experience certificate":"شهادة خبرة" };
  return rtl ? (ar[key] || key) : key;
};
const localizedStage = (value: unknown, rtl: boolean) => {
  const key = String(value || "").toLowerCase().replaceAll("_"," ");
  const ar:Record<string,string> = { manager:"المدير المباشر", "direct manager":"المدير المباشر", hr:"الموارد البشرية", employee:"الموظف", completed:"مكتمل" };
  return rtl ? (ar[key] || String(value || "—")) : String(value || "—").replaceAll("_"," ").replace(/\b\w/g,letter=>letter.toUpperCase());
};
const localizedCountry = (value: unknown, rtl: boolean) => {
  const key=String(value||"");
  const ar:Record<string,string>={"Saudi Arabia":"السعودية",KSA:"السعودية",Egypt:"مصر",Both:"السعودية ومصر","KSA & Egypt":"السعودية ومصر"};
  return rtl?(ar[key]||key):key.replace("KSA","Saudi Arabia");
};
const parseSetting = (row?:Record<string,any>) => { try { return JSON.parse(String(row?.value_json||"{}")) as Record<string,unknown>; } catch { return {}; } };
const localizedRole = (role: RoleId, rtl: boolean) => ({
  hr_manager: rtl ? "مدير الموارد البشرية" : "HR Manager",
  direct_manager: rtl ? "المدير المباشر" : "Direct Manager",
  employee: rtl ? "موظف" : "Employee",
  super_admin: rtl ? "مدير النظام" : "Super Admin",
}[role]);

const copy = {
  en: {
    dashboard: "Dashboard", portal: "Employee Portal", approvals: "Request Approvals",
    employees: "Employees", leave: "Leave Management", attendance: "Attendance",
    org: "Organization Chart", users: "Users & Permissions", settings: "Settings",
    search: "Search anything...", greeting: "Good morning, Ahmed", subtitle: "Here’s what’s happening with your team today.",
    newRequest: "New request", viewAll: "View all", pending: "Pending approvals",
  },
  ar: {
    dashboard: "لوحة التحكم", portal: "بوابة الموظف", approvals: "اعتماد الطلبات",
    employees: "الموظفون", leave: "إدارة الإجازات", attendance: "الحضور والانصراف",
    org: "الهيكل التنظيمي", users: "المستخدمون والصلاحيات", settings: "الإعدادات",
    search: "ابحث في النظام...", greeting: "صباح الخير، أحمد", subtitle: "إليك ملخص فريقك لهذا اليوم.",
    newRequest: "طلب جديد", viewAll: "عرض الكل", pending: "طلبات بانتظار الاعتماد",
  },
};

type HRData = {
  employees: Record<string, any>[]; departments: Record<string, any>[]; jobTitles: Record<string, any>[];
  requests: Record<string, any>[]; attendance: Record<string, any>[]; holidays: Record<string, any>[];
  roles: Record<string, any>[]; users: Record<string, any>[]; permissions: Record<string, any>[]; audit: Record<string, any>[];
  settings: Record<string, any>[];
  currentUser?: Record<string, any>;
};

async function hrApi(payload?: Record<string, unknown>) {
  const response = await fetch("/api/hr", payload ? { method:"POST", headers:{"content-type":"application/json"}, body:JSON.stringify(payload) } : { cache:"no-store" });
  const body = await response.json().catch(() => ({}));
  if (response.status === 401 && typeof window !== "undefined") window.dispatchEvent(new Event("portal-session-expired"));
  if (!response.ok) throw new Error(body.error || body.message || `Request failed (${response.status})`);
  return body;
}

function useHRData(rtl = false) {
  const [data,setData]=useState<HRData|null>(null); const [error,setError]=useState("");
  const load=async()=>{try{setError("");setData(await hrApi());}catch{setError(rtl?"تعذر تحميل البيانات. تحقق من الاتصال وحاول مرة أخرى.":"Unable to load data. Check your connection and try again.");}};
  useEffect(()=>{void load();},[rtl]);
  return {data,error,reload:load};
}

function Avatar({ initials, tone = "blue", small = false }: { initials: string; tone?: string; small?: boolean }) {
  return <span className={`avatar ${tone} ${small ? "small" : ""}`}>{initials}</span>;
}

function Status({ children, tone = "green" }: { children: React.ReactNode; tone?: string }) {
  return <span className={`status ${tone}`}><span />{children}</span>;
}

function personInitials(name: unknown) {
  return String(name || "—").split(/\s+/).filter(Boolean).map(part => part[0]).join("").slice(0, 2).toUpperCase();
}

function Empty({ icon: Icon = FileText, title, text }: { icon?: typeof FileText; title: string; text: string }) {
  return <div className="empty"><span className="empty-icon"><Icon size={22} /></span><h3>{title}</h3><p>{text}</p></div>;
}

export function HRApp() {
  const [authState,setAuthState]=useState<"checking"|"signed_in"|"signed_out">("checking");
  const [lang, setLang] = useState<Lang>("en");
  const [page, setPage] = useState<Page>("dashboard");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [requestOpen, setRequestOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [checkedIn, setCheckedIn] = useState(true);
  const [role, setRole] = useState<RoleId>("hr_manager");
  const t = copy[lang];
  const rtl = lang === "ar";
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = rtl ? "rtl" : "ltr";
  }, [lang, rtl]);
  useEffect(()=>{
    let active=true;
    void fetch("/api/auth",{cache:"no-store"}).then(response=>response.json()).then(body=>{if(active)setAuthState(body.authenticated?"signed_in":"signed_out");}).catch(()=>{if(active)setAuthState("signed_out");});
    const expire=()=>setAuthState("signed_out");
    window.addEventListener("portal-session-expired",expire);
    return()=>{active=false;window.removeEventListener("portal-session-expired",expire);};
  },[]);

  const logout=async()=>{try{await fetch("/api/auth",{method:"DELETE"});}finally{setAuthState("signed_out");setMobileOpen(false);}};
  if(authState==="checking") return <div className="auth-loading"><div><Activity size={20}/><span>جارٍ التحقق من تسجيل الدخول...</span></div></div>;
  if(authState==="signed_out") return <LoginPage onSuccess={()=>setAuthState("signed_in")}/>;

  const nav = [
    { id: "dashboard" as Page, label: t.dashboard, icon: LayoutDashboard },
    { id: "portal" as Page, label: t.portal, icon: CircleUserRound },
    { id: "approvals" as Page, label: t.approvals, icon: CheckCircle2, badge: 6 },
    { id: "employees" as Page, label: t.employees, icon: Users },
    { id: "leave" as Page, label: t.leave, icon: CalendarDays },
    { id: "attendance" as Page, label: t.attendance, icon: Clock3 },
    { id: "org" as Page, label: t.org, icon: Network },
    { id: "users" as Page, label: t.users, icon: ShieldCheck },
    { id: "settings" as Page, label: t.settings, icon: Settings },
  ];

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2600); };
  const currentTitle = nav.find(n => n.id === page)?.label;

  return (
    <div className="app" dir={rtl ? "rtl" : "ltr"} data-lang={lang}>
      <aside className={`sidebar ${mobileOpen ? "open" : ""}`}>
        <div className="brand"><img className="brand-logo" src="/sanad-logo.png" alt={rtl?"سند":"Sanad"} /><button className="mobile-close" onClick={() => setMobileOpen(false)} aria-label={rtl?"إغلاق القائمة":"Close menu"}><X size={20} /></button></div>
        <div className="workspace-label">{rtl ? "مساحة العمل" : "WORKSPACE"}</div>
        <nav>
          {nav.map(({ id, label, icon: Icon, badge }) => (
            <button key={id} className={page === id ? "active" : ""} onClick={() => { setPage(id); setMobileOpen(false); }}>
              <Icon size={19} strokeWidth={1.8} /><span>{label}</span>{badge && <em>{badge}</em>}
            </button>
          ))}
        </nav>
        <div className="sidebar-bottom">
          <button onClick={() => notify(rtl ? "مركز المساعدة قريباً" : "Help center is coming soon")}><HelpCircle size={19} /><span>{rtl ? "المساعدة والدعم" : "Help & support"}</span></button>
          <div className="profile-mini"><Avatar initials="AE" small /><div><b>{rtl ? "أحمد الشيوي" : "Ahmed Elshewy"}</b><span>{localizedRole(role,rtl)}</span></div><button className="profile-logout" onClick={()=>void logout()} aria-label={rtl?"تسجيل الخروج":"Sign out"}><LogOut size={14}/><span>{rtl?"خروج":"Logout"}</span></button></div>
        </div>
      </aside>
      {mobileOpen && <button className="scrim" onClick={() => setMobileOpen(false)} aria-label="Close navigation" />}

      <main className="main">
        <header className="topbar">
          <button className="menu-btn" onClick={() => setMobileOpen(true)} aria-label={rtl?"فتح قائمة التنقل":"Open navigation"}><Menu size={21} /></button>
          <div className="mobile-title">{currentTitle}</div>
          <button className="global-search" onClick={() => { setPage("employees"); notify(rtl ? "افتح البحث داخل قائمة الموظفين للوصول إلى أي سجل" : "Use the employee list search to find any record"); }}><Search size={18} /><span>{t.search}</span><kbd>⌘ K</kbd></button>
          <div className="top-actions">
            <label className="role-select"><ShieldCheck size={16} /><select aria-label={rtl?"الدور الحالي":"Current role"} value={role} onChange={e => setRole(e.target.value as RoleId)}>{(["hr_manager","direct_manager","employee","super_admin"] as RoleId[]).map(id=><option value={id} key={id}>{localizedRole(id,rtl)}</option>)}</select><ChevronDown size={14} /></label>
            <button className="language" onClick={() => setLang(lang === "en" ? "ar" : "en")}><Languages size={17} />{lang === "en" ? "العربية" : "English"}</button>
            <button className="icon-btn notification-btn" onClick={() => setNotificationsOpen(!notificationsOpen)} aria-label={rtl?"الإشعارات":"Notifications"}><Bell size={19} /><span /></button>
            <Avatar initials="AE" small />
          </div>
          {notificationsOpen && <Notifications rtl={rtl} onClose={() => setNotificationsOpen(false)} openPage={setPage} />}
        </header>

        <div className="content">
          {page === "dashboard" && <Dashboard rtl={rtl} t={t} setPage={setPage} openRequest={() => setRequestOpen(true)} notify={notify} />}
          {page === "portal" && <Portal rtl={rtl} openRequest={() => setRequestOpen(true)} checkedIn={checkedIn} setCheckedIn={setCheckedIn} notify={notify} />}
          {page === "approvals" && <Approvals rtl={rtl} notify={notify} />}
          {page === "employees" && <EmployeesPage rtl={rtl} notify={notify} />}
          {page === "leave" && <LeavePage rtl={rtl} notify={notify} />}
          {page === "attendance" && <AttendancePage rtl={rtl} notify={notify} />}
          {page === "org" && <OrgPage rtl={rtl} notify={notify} />}
          {page === "users" && <UsersPage rtl={rtl} notify={notify} />}
          {page === "settings" && <SettingsPage rtl={rtl} notify={notify} />}
        </div>
      </main>
      {requestOpen && <RequestDrawer rtl={rtl} close={() => setRequestOpen(false)} submit={async payload => { await hrApi({action:"create_request",...payload}); setRequestOpen(false); notify(rtl?"تم إرسال الطلب وحفظه بنجاح":"Request submitted and saved successfully"); }} />}
      {toast && <div className="toast"><CheckCircle2 size={19} />{toast}</div>}
    </div>
  );
}

function LoginPage({onSuccess}:{onSuccess:()=>void}){
  const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [loading,setLoading]=useState(false);
  const submit=async(event:React.FormEvent)=>{event.preventDefault();setError("");setLoading(true);try{const response=await fetch("/api/auth",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email,password})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"تعذر تسجيل الدخول");onSuccess();}catch(reason){setError(reason instanceof Error?reason.message:"تعذر تسجيل الدخول");}finally{setLoading(false);}};
  return <main className="login-page" dir="rtl"><section className="login-panel"><img className="login-logo" src="/sanad-logo.png" alt="Sanad HR"/><div className="login-copy"><small>نظام إدارة الموارد البشرية</small><h1>مرحبًا بعودتك</h1><p>سجّل الدخول للوصول إلى لوحة التحكم وبيانات فريق العمل.</p></div><form className="login-form" onSubmit={event=>void submit(event)}><label className="login-field"><span>البريد الإلكتروني</span><div className="login-input"><CircleUserRound size={18}/><input type="email" autoComplete="username" value={email} onChange={event=>setEmail(event.target.value)} placeholder="name@company.com" required dir="ltr"/></div></label><label className="login-field"><span>كلمة المرور</span><div className="login-input"><KeyRound size={18}/><input type="password" autoComplete="current-password" value={password} onChange={event=>setPassword(event.target.value)} placeholder="••••••••" required dir="ltr"/></div></label>{error&&<p className="login-error" role="alert">{error}</p>}<button className="login-submit" type="submit" disabled={loading}>{loading?<><Activity size={18}/>جارٍ تسجيل الدخول...</>:<><LogOut size={17}/>تسجيل الدخول</>}</button></form><p className="login-note">الدخول مخصص للمستخدمين المصرح لهم فقط</p></section><section className="login-visual"><div className="login-visual-content"><span className="login-visual-icon"><ShieldCheck size={29}/></span><h2>كل ما يخص فريقك<br/>في مكان واحد</h2><p>إدارة الموظفين والحضور والإجازات والهيكل التنظيمي من بوابة واحدة آمنة وسهلة.</p><div className="login-features"><span>إدارة الموظفين</span><span>الحضور والانصراف</span><span>الإجازات والطلبات</span><span>الهيكل التنظيمي</span></div></div></section></main>
}

function Dashboard({ rtl, t, setPage, openRequest, notify }: { rtl: boolean; t: typeof copy.en; setPage: (p: Page) => void; openRequest: () => void; notify:(message:string)=>void }) {
  const stats = [
    { label: rtl ? "إجمالي الموظفين" : "Total employees", value: formatNumber(126,rtl), note: rtl ? `+${formatNumber(4,rtl)} هذا الشهر` : "+4 this month", icon: Users, tone: "blue" },
    { label: rtl ? "الحاضرون اليوم" : "Present today", value: formatNumber(109,rtl), note: new Intl.NumberFormat(localeFor(rtl),{style:"percent",maximumFractionDigits:1}).format(.865), icon: CheckCircle2, tone: "green" },
    { label: rtl ? "في إجازة" : "On leave", value: formatNumber(8,rtl), note: rtl ? `${formatNumber(3,rtl)} أقسام` : "3 departments", icon: CalendarDays, tone: "violet" },
    { label: rtl ? "المتأخرون اليوم" : "Late today", value: formatNumber(5,rtl), note: rtl ? `أقل بـ${formatNumber(2,rtl)} من الأمس` : "2 fewer than yesterday", icon: Clock3, tone: "orange" },
  ];
  return <>
    <section className="page-heading"><div><span className="eyebrow">{formatDate("2026-08-14",rtl,{weekday:"long",day:"numeric",month:"long",year:"numeric"})}</span><h1>{t.greeting} <span>👋</span></h1><p>{t.subtitle}</p></div><button className="primary" onClick={openRequest}><Plus size={17} />{t.newRequest}</button></section>
    <section className="stat-grid">{stats.map(({ label, value, note, icon: Icon, tone }) => <div className="stat-card" key={label}><div className={`stat-icon ${tone}`}><Icon size={20} /></div><div className="stat-value">{value}</div><div className="stat-label">{label}</div><div className={`stat-note ${tone}`}>{note}</div></div>)}</section>
    <section className="dashboard-grid">
      <div className="panel attendance-overview"><div className="panel-head"><div><h2>{rtl ? "ملخص الحضور" : "Attendance overview"}</h2><p>{rtl ? "معدل الحضور اليومي خلال الأسبوع الحالي" : "Daily attendance across the current week"}</p></div><button className="select-button" onClick={()=>notify(rtl?"يعرض الرسم بيانات الأسبوع الحالي":"The chart is showing the current week")} aria-label={rtl?"نطاق تقرير الحضور":"Attendance report period"}>{rtl ? "الأسبوع الحالي" : "This week"}<ChevronDown size={15} /></button></div><div className="legend"><span className="present">{rtl ? "حضور مكتبي" : "On-site"}</span><span className="remote">{rtl ? "عمل عن بُعد" : "Remote"}</span><span className="away">{rtl ? "غياب أو إجازة" : "Absent or on leave"}</span></div><div className="chart">{[72,88,81,92,86,0,0].map((v,i) => <div className="bar-col" key={i}><div className="bar-track"><span className="bar-away" style={{height: `${v ? 100-v : 2}%`}}/><span className="bar-remote" style={{height: `${v ? 10+i%3*3 : 0}%`}}/><span className="bar-present" style={{height: `${v}%`}}/></div><small>{(rtl?["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"]:["Sun","Mon","Tue","Wed","Thu","Fri","Sat"])[i]}</small></div>)}</div>
      </div>
      <div className="panel today-card"><div className="panel-head"><div><h2>{rtl ? "حضوري اليوم" : "My attendance today"}</h2><p>{formatDate("2026-08-14",rtl)}</p></div><Status>{rtl ? "حاضر" : "Present"}</Status></div><div className="time-ring"><div><Clock3 size={25}/><strong>{rtl?"٠٦:١٨":"06:18"}</strong><span>{rtl ? "ساعات مسجلة" : "hours worked"}</span></div></div><div className="time-points"><div><span>{formatTime("08:57",rtl)}</span><small>{rtl ? "وقت الحضور" : "Check-in"}</small></div><div><span>—</span><small>{rtl ? "وقت الانصراف" : "Check-out"}</small></div></div><button className="outline wide directional" onClick={() => setPage("portal")}>{rtl ? "إدارة الحضور عن بُعد" : "Manage remote attendance"}<ChevronRight size={16}/></button></div>
    </section>
    <section className="dashboard-grid lower">
      <div className="panel approvals-card"><div className="panel-head"><div><h2>{t.pending}</h2><p>{rtl ? `${formatNumber(6,rtl)} طلبات تتطلب إجراءك` : "6 requests need your action"}</p></div><button className="text-button directional" onClick={() => setPage("approvals")}>{t.viewAll}<ChevronRight size={15}/></button></div>{requests.map(r => <div className="approval-row" key={r.id}><Avatar initials={r.name.split(" ").map(x=>x[0]).join("")} tone={r.tone}/><div className="request-main"><b>{rtl?r.nameAr:r.name}</b><span>{localizedRequestType(r.type,rtl)} · {r.amount?new Intl.NumberFormat(localeFor(rtl),{style:"currency",currency:"SAR",maximumFractionDigits:0}).format(r.amount):r.from===r.to?formatDate(r.from,rtl,{day:"numeric",month:"short"}):`${formatDate(r.from!,rtl,{day:"numeric"})}–${formatDate(r.to!,rtl,{day:"numeric",month:"short"})}`}</span></div><small>{formatDate(r.submitted,rtl,{day:"numeric",month:"short"})}</small><button className="round-check" onClick={()=>setPage("approvals")} aria-label={rtl?"فتح الطلب لاعتماده":"Open request for approval"}><Check size={16}/></button><button className="round-more" onClick={()=>setPage("approvals")} aria-label={rtl?"عرض تفاصيل الطلب":"View request details"}><MoreHorizontal size={17}/></button></div>)}</div>
      <div className="panel leave-card"><div className="panel-head"><div><h2>{rtl ? "رصيد الإجازات" : "Leave balance"}</h2><p>{rtl ? `العام ${formatNumber(2026,rtl)}` : "For 2026"}</p></div><button className="text-button directional" onClick={() => setPage("portal")}>{t.viewAll}<ChevronRight size={15}/></button></div><div className="balance"><div className="balance-ring"><strong>{formatNumber(18,rtl)}</strong><span>{rtl ? "يوماً متبقياً" : "days left"}</span></div><div className="balance-info"><div><span>{rtl ? "الرصيد السنوي" : "Annual entitlement"}</span><b>{rtl?`${formatNumber(30,rtl)} يوماً`:"30 days"}</b></div><div><span>{rtl ? "المستخدم" : "Used"}</span><b>{rtl?`${formatNumber(10,rtl)} أيام`:"10 days"}</b></div><div><span>{rtl ? "طلبات معلقة" : "Pending"}</span><b>{rtl?`${formatNumber(2,rtl)} يومان`:"2 days"}</b></div></div></div><div className="holiday-next"><CalendarDays size={19}/><div><small>{rtl ? "العطلة القادمة" : "Next holiday"}</small><b>{rtl ? "المولد النبوي الشريف" : "Prophet’s Birthday"}</b></div><span>{formatDate("2026-08-26",rtl,{day:"numeric",month:"short"})}</span></div></div>
    </section>
  </>;
}

function Portal({ rtl, openRequest, checkedIn, setCheckedIn, notify }: { rtl:boolean; openRequest:()=>void; checkedIn:boolean; setCheckedIn:(v:boolean)=>void; notify:(s:string)=>void }) {
  const [tab,setTab]=useState("requests");
  const recordAttendance=async()=>{try{await hrApi({action:"attendance_event",eventType:checkedIn?"check_out":"check_in"});setCheckedIn(!checkedIn);notify(checkedIn?(rtl?"تم تسجيل الانصراف بنجاح":"Check-out recorded"):(rtl?"تم تسجيل الحضور بنجاح":"Check-in recorded"));}catch(e){notify(e instanceof Error?e.message:(rtl?"تعذر تسجيل الحضور، حاول مرة أخرى":"Attendance action failed"));}};
  const weekDays = rtl?["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس"]:["Sunday","Monday","Tuesday","Wednesday","Thursday"];
  return <><PageHeader eyebrow={rtl?"الخدمة الذاتية للموظف":"EMPLOYEE SELF-SERVICE"} title={rtl?"بوابة الموظف":"Employee portal"} text={rtl?"تابع طلباتك وحضورك ورصيد إجازاتك من مكان واحد.":"Manage your requests, attendance and leave balance in one place."} action={<button className="primary" onClick={openRequest}><Plus size={17}/>{rtl?"تقديم طلب":"New request"}</button>}/><Tabs items={[{id:"requests",label:rtl?"طلباتي":"My requests"},{id:"remote",label:rtl?"الحضور عن بُعد":"Remote attendance"}]} active={tab} setActive={setTab}/>{tab==="requests"?<div className="panel table-panel"><FilterBar rtl={rtl}/><RequestTable rtl={rtl}/></div>:<div className="remote-layout"><div className="panel remote-card"><span className="date-chip">{formatDate("2026-08-14",rtl,{weekday:"long",day:"numeric",month:"long",year:"numeric"})}</span><div className="live-time">{formatTime("10:42",rtl)}</div><p>{rtl?"توقيت الرياض (UTC+3)":"Riyadh time (UTC+3)"}</p><div className={`pulse ${checkedIn?"active":""}`}><Clock3 size={28}/></div><Status tone={checkedIn?"green":"gray"}>{checkedIn?(rtl?"الدوام مسجّل":"Active session"):(rtl?"لم تسجّل الحضور":"Not checked in")}</Status><div className="session-summary"><div><small>{rtl?"وقت الحضور":"CHECK-IN"}</small><b>{checkedIn?formatTime("08:57",rtl):"—"}</b></div><div><small>{rtl?"المدة المسجلة":"WORKED"}</small><b>{checkedIn?(rtl?"ساعة و٤٥ دقيقة":"1 hr 45 min"):"—"}</b></div></div><button className={checkedIn?"danger-action":"primary wide"} onClick={()=>void recordAttendance()}>{checkedIn?(rtl?"تسجيل الانصراف":"Check out"):(rtl?"تسجيل الحضور":"Check in")}</button><small className="privacy"><ShieldCheck size={14}/>{rtl?"يُستخدم موقعك التقريبي لإثبات الحضور فقط":"Approximate location is used for attendance verification only"}</small></div><div className="panel week-card"><div className="panel-head"><div><h2>{rtl?"الأسبوع الحالي":"This week"}</h2><p>{rtl?"سجل ساعات العمل اليومية":"Your daily work record"}</p></div><b>{rtl?"٣٢ ساعة و١٤ دقيقة":"32 hr 14 min"}</b></div>{weekDays.map((day,i)=><div className="day-row" key={day}><span className={i===4?"day-badge today":"day-badge"}>{formatNumber(i+10,rtl)}</span><div><b>{day}</b><small>{i===4?`${formatTime("08:57",rtl)} — ${rtl?"الدوام مستمر":"Active"}`:`${formatTime("09:00",rtl)} — ${formatTime("17:05",rtl)}`}</small></div><span>{i===4?(rtl?"ساعة و٤٥ د":"1 hr 45 min"):(rtl?"٨ ساعات و٤ د":"8 hr 4 min")}</span></div>)}</div></div>}</>;
}

function Approvals({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){const [tab,setTab]=useState("pending");const {data,error,reload}=useHRData();const all=data?.requests??[];const list=all.filter(r=>tab==="all"||(tab==="pending"?String(r.status).startsWith("pending"):tab==="approved"?String(r.status).includes("approved"):String(r.status).includes("rejected")));const decide=async(id:number,decision:"approve"|"reject")=>{const reason=decision==="reject"?(window.prompt(rtl?"اكتب سبب الرفض":"Rejection reason")||""):"";if(decision==="reject"&&!reason)return;try{await hrApi({action:"request_action",requestId:id,decision,reason});await reload();notify(decision==="approve"?(rtl?"تم اعتماد الطلب وتحويله إلى المرحلة التالية":"Request approved and moved to the next stage"):(rtl?"تم رفض الطلب وحفظ السبب":"Request rejected and the reason was recorded"));}catch(e){notify(e instanceof Error?e.message:(rtl?"تعذر تنفيذ الإجراء":"Action failed"));}};return <><PageHeader eyebrow={rtl?"مسار الاعتمادات":"WORKFLOW"} title={rtl?"اعتماد الطلبات":"Request approvals"} text={rtl?"راجع طلبات فريقك واتخذ الإجراء المناسب من قائمة موحّدة.":"Review team requests and take action from one focused queue."}/><Tabs items={[{id:"pending",label:`${rtl?"بانتظار اعتمادي":"Awaiting my approval"} (${formatNumber(all.filter(r=>String(r.status).startsWith("pending")).length,rtl)})`},{id:"approved",label:rtl?"المعتمدة":"Approved"},{id:"rejected",label:rtl?"المرفوضة":"Rejected"},{id:"all",label:rtl?"جميع الطلبات":"All requests"}]} active={tab} setActive={setTab}/><div className="panel table-panel">{error&&<div className="error-banner">{error}</div>}<FilterBar rtl={rtl}/>{list.length===0?<Empty title={rtl?"لا توجد طلبات":"No requests found"} text={rtl?"لا توجد طلبات مطابقة لعوامل التصفية الحالية.":"No requests match the current filters."}/>:<div className="data-table approval-table"><div className="tr th"><span>{rtl?"الموظف":"Employee"}</span><span>{rtl?"نوع الطلب":"Request"}</span><span>{rtl?"الفترة":"Period"}</span><span>{rtl?"مرحلة الاعتماد":"Approval stage"}</span><span>{rtl?"الحالة":"Status"}</span><span></span></div>{list.map((r,i)=><div className="tr" key={r.id}><span className="person"><Avatar initials={personInitials(r.employee_name)} small tone={["blue","violet","rose"][i%3]}/><span><b>{rtl?(r.employee_name_ar||r.employee_name):r.employee_name}</b><small>{rtl?(r.department_name_ar||r.department_name):r.department_name||"—"}</small></span></span><span><b>{localizedRequestType(r.type,rtl)}</b><small>{r.request_code}</small></span><span>{r.from_date&&r.to_date?`${formatDate(r.from_date,rtl,{day:"numeric",month:"short"})} — ${formatDate(r.to_date,rtl,{day:"numeric",month:"short"})}`:(r.request_date?formatDate(r.request_date,rtl):"—")}</span><span><small>{localizedStage(r.current_stage,rtl)}</small></span><span><Status tone={String(r.status).includes("rejected")?"rose":String(r.status).includes("approved")?"green":"amber"}>{localizedStatus(r.status,rtl)}</Status></span><span className="row-actions">{String(r.status).startsWith("pending")&&<><button onClick={()=>void decide(r.id,"approve")} aria-label={rtl?"اعتماد الطلب":"Approve request"}><Check size={15}/></button><button onClick={()=>void decide(r.id,"reject")} aria-label={rtl?"رفض الطلب":"Reject request"}><X size={15}/></button></>}</span></div>)}</div>}</div></>}

function EmployeesPage({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){
  const [tab,setTab]=useState("employees"); const [open,setOpen]=useState(false); const [selected,setSelected]=useState<Record<string,any>|null>(null);const [entityEditor,setEntityEditor]=useState<{kind:"job_title"|"department";record?:Record<string,any>}|null>(null); const {data,error,reload}=useHRData();
  const total=data?.employees.length??0, active=data?.employees.filter(e=>e.employment_status==="active").length??0;
  const ksa=data?.employees.filter(e=>e.country==="Saudi Arabia").length??0, egypt=data?.employees.filter(e=>e.country==="Egypt").length??0;
  const action=tab==="employees"?<button className="primary" onClick={()=>setOpen(true)}><Plus size={17}/>{rtl?"إضافة موظف":"Add employee"}</button>:tab==="jobs"?<button className="primary" onClick={()=>setEntityEditor({kind:"job_title"})}><Plus size={17}/>{rtl?"إضافة مسمى":"Add job title"}</button>:<button className="primary" onClick={()=>setEntityEditor({kind:"department"})}><Plus size={17}/>{rtl?"إضافة قسم":"Add department"}</button>;
  return <><PageHeader eyebrow={rtl?"إدارة الموارد البشرية":"PEOPLE MANAGEMENT"} title={rtl?"الموظفون":"Employees"} text={rtl?"إدارة ملفات الموظفين والمسميات الوظيفية والأقسام من مكان واحد.":"Manage employee records, job titles and departments in one place."} action={action}/>
  {error&&<div className="error-banner">{error}<button onClick={()=>void reload()}>{rtl?"إعادة المحاولة":"Retry"}</button></div>}
  <section className="mini-stats"><div><Users/><span><b>{total?formatNumber(total,rtl):"—"}</b>{rtl?"إجمالي الموظفين":"Total employees"}</span></div><div><CheckCircle2/><span><b>{active?formatNumber(active,rtl):"—"}</b>{rtl?"الموظفون النشطون":"Active employees"}</span></div><div><Globe2/><span><b>{formatNumber(ksa,rtl)} / {formatNumber(egypt,rtl)}</b>{rtl?"السعودية / مصر":"Saudi Arabia / Egypt"}</span></div><div><BriefcaseBusiness/><span><b>{formatNumber(data?.employees.filter(e=>String(e.created_at).startsWith("2026-08")).length??0,rtl)}</b>{rtl?"منضمون هذا الشهر":"Joined this month"}</span></div></section>
  <Tabs items={[{id:"employees",label:rtl?"الموظفون":"Employees"},{id:"jobs",label:rtl?"المسميات الوظيفية":"Job titles"},{id:"departments",label:rtl?"الأقسام":"Departments"}]} active={tab} setActive={setTab}/><div className="panel table-panel"><FilterBar rtl={rtl}/>{tab==="employees"?<EmployeeTable rtl={rtl} rows={data?.employees} onSelect={setSelected}/>:tab==="jobs"?<JobTitleTable rtl={rtl} rows={data?.jobTitles} departments={data?.departments} onEdit={record=>setEntityEditor({kind:"job_title",record})}/>:<DepartmentGrid rtl={rtl} rows={data?.departments} jobs={data?.jobTitles} employees={data?.employees} reload={reload} notify={notify} onEdit={record=>setEntityEditor({kind:"department",record})}/>}</div>
  {open&&<EmployeeDrawer rtl={rtl} data={data} close={()=>setOpen(false)} submit={async(form)=>{await hrApi({action:"create_employee",...form});setOpen(false);await reload();notify(rtl?"تم إنشاء الموظف وحساب المستخدم بنجاح":"Employee and user account created successfully");}}/>}
  {selected&&<EmployeeDetailsDrawer rtl={rtl} employee={selected} data={data} close={()=>setSelected(null)} submit={async form=>{await hrApi({action:"update_employee",...form});await reload();setSelected(null);notify(rtl?"تم تحديث بيانات الموظف بنجاح":"Employee details updated successfully");}}/>}
  {entityEditor&&<OrganizationEntityDrawer rtl={rtl} kind={entityEditor.kind} record={entityEditor.record} departments={data?.departments??[]} close={()=>setEntityEditor(null)} submit={async form=>{const editing=Boolean(entityEditor.record?.id);await hrApi({action:entityEditor.kind==="job_title"?"save_job_title":"save_department",...form});await reload();setEntityEditor(null);notify(entityEditor.kind==="job_title"?(editing?(rtl?"تم تعديل المسمى الوظيفي":"Job title updated"):(rtl?"تمت إضافة المسمى الوظيفي":"Job title added")):(editing?(rtl?"تم تعديل القسم":"Department updated"):(rtl?"تمت إضافة القسم":"Department added")));}}/>}</>}

function LeavePage({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){const [tab,setTab]=useState("holidays"),[open,setOpen]=useState(false);const {data,error,reload}=useHRData();const settings=tab==="settings"?(rtl?[{t:"تعديل مواعيد العطلات",d:"نقل العطلة الرسمية إلى يوم بديل عند الحاجة",n:"إعدادان نشطان"},{t:"تقويم الدول",d:"تحديد أيام العمل والعطلات لكل دولة",n:"دولتان"},{t:"مسار الاعتماد",d:"مراحل اعتماد المدير المباشر والموارد البشرية",n:"قياسي"}]:[{t:"Holiday adjustments",d:"Move an official holiday to a replacement date",n:"2 active"},{t:"Country calendars",d:"Configure working days and holidays by country",n:"2 countries"},{t:"Approval workflow",d:"Manager and HR approval stages",n:"Standard"}]):(rtl?[{t:"الإجازة السنوية",d:"استحقاق يراعي الدولة ومدة الخدمة",n:"سياستان"},{t:"الإجازة المرضية",d:"يلزم تقرير طبي بعد يومين",n:"نشطة"},{t:"ترحيل الرصيد",d:"ترحيل ٥ أيام بحد أقصى لمدة ٩٠ يوماً",n:"مُعدّ"}]:[{t:"Annual leave",d:"Entitlement based on country and length of service",n:"2 policies"},{t:"Sick leave",d:"Medical certificate required after 2 days",n:"Active"},{t:"Carry forward",d:"Up to 5 days, expiring after 90 days",n:"Configured"}]);return <><PageHeader eyebrow={rtl?"السياسات والتقويم":"POLICIES & CALENDAR"} title={rtl?"إدارة الإجازات":"Leave management"} text={rtl?"إدارة العطلات الرسمية وسياسات الإجازات في السعودية ومصر.":"Manage official holidays and leave policies across Saudi Arabia and Egypt."} action={<button className="primary" onClick={()=>setOpen(true)}><Plus size={17}/>{rtl?"إضافة عطلة رسمية":"Add holiday"}</button>}/>{error&&<div className="error-banner">{error}</div>}<Tabs items={[{id:"holidays",label:rtl?"العطلات الرسمية":"Official holidays"},{id:"settings",label:rtl?"إعدادات الإجازات":"Leave settings"},{id:"policies",label:rtl?"سياسات الإجازات":"Leave policies"}]} active={tab} setActive={setTab}/>{tab==="holidays"?<HolidayCalendar rtl={rtl} rows={data?.holidays}/>:<div className="settings-grid">{settings.map((x,i)=><button className="panel setting-card setting-button directional" key={x.t} onClick={()=>notify(rtl?"تم فتح الإعداد في محرر السياسات":"Setting opened in the policy editor")}><span className={`setting-icon ${["blue","violet","green"][i]}`}><SlidersHorizontal/></span><div><h3>{x.t}</h3><p>{x.d}</p></div><Status tone={i===1?"violet":"green"}>{x.n}</Status><ChevronRight/></button>)}</div>}{open&&<HolidayDrawer rtl={rtl} close={()=>setOpen(false)} submit={async form=>{await hrApi({action:"create_holiday",...form});setOpen(false);await reload();notify(rtl?"تم حفظ العطلة وإضافتها إلى احتساب الحضور":"Holiday saved and included in attendance calculations");}}/>}</>}

function AttendancePage({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){const [tab,setTab]=useState("management");return <><PageHeader eyebrow={rtl?"الوقت والحضور":"TIME & ATTENDANCE"} title={rtl?"الحضور والانصراف":"Attendance"} text={rtl?"سجلات موحدة من أجهزة البصمة والعمل عن بعد والتعديلات.":"One reconciled view across devices, remote work and corrections."} action={<button className="outline" onClick={()=>notify(rtl?"جارٍ إعداد ملف Excel":"Excel export prepared with active filters")}><Download size={17}/>{rtl?"تصدير Excel":"Export Excel"}</button>}/><Tabs items={[{id:"logs",label:rtl?"سجلات الحضور":"Attendance logs"},{id:"management",label:rtl?"إدارة الحضور":"Attendance management"}]} active={tab} setActive={setTab}/><div className="panel table-panel"><FilterBar rtl={rtl}/><AttendanceTable rtl={rtl} logs={tab==="logs"}/></div></>}

function OrgPage({rtl,notify}:{rtl:boolean;notify:(message:string)=>void}){
  const {data,error,reload}=useHRData();
  const [query,setQuery]=useState("");
  const [editingLevels,setEditingLevels]=useState(false);
  const [savingLevels,setSavingLevels]=useState(false);
  const [levelDrafts,setLevelDrafts]=useState<Record<number,number>>({});
  const departments=data?.departments??[], employeesData=data?.employees??[], jobs=data?.jobTitles??[];
  const directorDepartment=departments.find(department=>/Managing Director|العضو المنتدب/i.test(`${department.name_en} ${department.name_ar}`));
  const director=employeesData.find(employee=>Number(employee.department_id)===Number(directorDepartment?.id)) ?? employeesData.find(employee=>/Chief Executive|الرئيس التنفيذ/i.test(String(employee.job_title_name||"")));
  const jobById=new Map(jobs.map(job=>[Number(job.id),job]));
  const normalized=query.trim().toLocaleLowerCase();
  const childDepartments=(parentId:number)=>departments.filter(department=>Number(department.parent_id)===parentId);
  const departmentMembers=(departmentId:number)=>employeesData.filter(employee=>Number(employee.department_id)===departmentId);
  const departmentMatches=(department:Record<string,any>):boolean=>{const ownText=`${department.name_en} ${department.name_ar} ${departmentMembers(Number(department.id)).map(member=>`${member.name_en} ${member.name_ar}`).join(" ")}`.toLocaleLowerCase();return !normalized||ownText.includes(normalized)||childDepartments(Number(department.id)).some(departmentMatches);};
  const divisions=childDepartments(Number(directorDepartment?.id)).filter(departmentMatches);
  const directorJob=director?jobById.get(Number(director.job_title_id)):undefined;
  const totalEmployees=employeesData.length;
  const activeDepartments=departments.filter(department=>Number(department.id)!==Number(directorDepartment?.id));
  const leaders=activeDepartments.filter(department=>Number(department.manager_employee_id)>0).length;
  const largestDepartment=[...activeDepartments].sort((a,b)=>departmentMembers(Number(b.id)).length-departmentMembers(Number(a.id)).length)[0];
  const leadershipCoverage=activeDepartments.length?Math.round(leaders/activeDepartments.length*100):0;
  const beginLevelEditing=()=>{setLevelDrafts(Object.fromEntries(employeesData.map(employee=>[Number(employee.id),Number(employee.organizational_level??1)])));setEditingLevels(true);};
  const saveLevels=async()=>{try{setSavingLevels(true);await hrApi({action:"save_organization_levels",assignments:employeesData.map(employee=>({employeeId:Number(employee.id),level:levelDrafts[Number(employee.id)]??Number(employee.organizational_level??1)}))});await reload();setEditingLevels(false);notify(rtl?"تم حفظ أرقام المستويات":"Organization levels saved");}catch(reason){notify(reason instanceof Error?reason.message:(rtl?"تعذر حفظ المستويات":"Unable to save levels"));}finally{setSavingLevels(false);}};
  return <><PageHeader eyebrow={rtl?"الهيكل الإداري":"ORGANIZATION STRUCTURE"} title={rtl?"الرئيس التنفيذي وقطاعات الشركة":"CEO & company divisions"} text={rtl?"ثلاثة قطاعات مستقلة، تتفرع منها الإدارات والفرق والموظفون.":"Three distinct divisions, followed by their departments, teams and employees."}/>
  {error&&<div className="error-banner">{error}<button onClick={()=>void reload()}>{rtl?"إعادة المحاولة":"Retry"}</button></div>}
  <section className="org-insights" aria-label={rtl?"ملخص الهيكل":"Structure summary"}>
    <div className="org-insight primary-insight"><span><Users size={19}/></span><div><b>{formatNumber(totalEmployees,rtl)}</b><small>{rtl?"إجمالي الموظفين":"total employees"}</small></div><em>{rtl?`${formatNumber(divisions.length,rtl)} قطاعات`:`${divisions.length} divisions`}</em></div>
    <div className="org-insight"><span><Building2 size={19}/></span><div><b>{largestDepartment?rtl?largestDepartment.name_ar:largestDepartment.name_en:"—"}</b><small>{rtl?"أكبر إدارة":"largest department"}</small></div><em>{largestDepartment?formatNumber(departmentMembers(Number(largestDepartment.id)).length,rtl):0}</em></div>
    <div className="org-insight"><span><ShieldCheck size={19}/></span><div><b>{new Intl.NumberFormat(localeFor(rtl),{style:"percent",maximumFractionDigits:0}).format(leadershipCoverage/100)}</b><small>{rtl?"نسبة الأقسام ذات مدير معتمد":"leadership coverage"}</small></div><em>{formatNumber(leaders,rtl)}/{formatNumber(activeDepartments.length,rtl)}</em></div>
    <div className="org-insight"><span><BriefcaseBusiness size={19}/></span><div><b>{formatNumber(jobs.length,rtl)}</b><small>{rtl?"مسمى وظيفي":"job titles"}</small></div><em>{rtl?"تنوع الأدوار":"role mix"}</em></div>
  </section>
  <div className="org-toolbar"><div><b>{rtl?"التسلسل من الرئيس التنفيذي إلى الموظفين":"CEO-to-employee hierarchy"}</b><small>{rtl?"كون · أسس · وكالة كون":"Koon · Asus · Koon Agency"}</small></div><span></span>{editingLevels?<div className="org-level-actions"><button className="outline" onClick={()=>setEditingLevels(false)} disabled={savingLevels}><X size={15}/>{rtl?"إلغاء":"Cancel"}</button><button className="primary" onClick={()=>void saveLevels()} disabled={savingLevels}><Check size={15}/>{savingLevels?(rtl?"جارٍ الحفظ":"Saving"):(rtl?"حفظ الأرقام":"Save numbers")}</button></div>:<button className="org-edit-levels" onClick={beginLevelEditing}><SlidersHorizontal size={16}/>{rtl?"تعديل المستويات":"Edit levels"}</button>}<label className="org-search"><Search size={17}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={rtl?"ابحث عن قسم أو موظف":"Find a department or employee"}/>{query&&<button onClick={()=>setQuery("")} aria-label={rtl?"مسح البحث":"Clear search"}><X size={14}/></button>}</label></div>
  <div className="panel org-canvas">
    {director?<div className="org-executive"><span className="org-level-label">{rtl?"الرئيس التنفيذي":"CHIEF EXECUTIVE OFFICER"}</span><div className="org-executive-card"><Avatar initials={personInitials(director.name_en)} tone="blue"/><div><small>{rtl?"تتبعه القطاعات الرئيسية الثلاثة":"THREE MAIN DIVISIONS REPORT TO"}</small><b>{rtl?director.name_ar:director.name_en}</b><span>{rtl?(directorJob?.name_ar||director.job_title_name):(directorJob?.name_en||director.job_title_name)}</span></div><em>{director.employee_code}</em></div><div className="org-main-connector"><span>{formatNumber(divisions.length,rtl)} {rtl?"قطاعات مباشرة":"direct divisions"}</span></div></div>:<Empty icon={Network} title={rtl?"لم يتم العثور على الرئيس التنفيذي":"Chief executive not found"} text={rtl?"تحقق من بيانات مكتب الرئيس التنفيذي.":"Check the chief-executive office data."}/>} 
    <div className="org-department-grid org-division-tree">{divisions.map((department,index)=><OrgDepartmentTreeNode key={department.id} rtl={rtl} department={department} departments={departments} employees={employeesData} jobs={jobs} tone={["blue","violet","green"][index%3]} depth={0} normalizedQuery={normalized} editingLevels={editingLevels} levelDrafts={levelDrafts} setLevel={(employeeId,level)=>setLevelDrafts(current=>({...current,[employeeId]:Math.max(1,Math.min(20,level||1))}))}/>)}</div>
    {data&&divisions.length===0&&<Empty icon={Building2} title={rtl?"لا توجد نتائج مطابقة":"No matching results"} text={rtl?"غيّر عبارة البحث لعرض الهيكل بالكامل.":"Change the search to show the complete hierarchy."}/>} 
  </div></>}

function OrgDepartmentTreeNode({rtl,department,departments,employees,jobs,tone,depth,normalizedQuery,editingLevels,levelDrafts,setLevel}:{rtl:boolean;department:Record<string,any>;departments:Record<string,any>[];employees:Record<string,any>[];jobs:Record<string,any>[];tone:string;depth:number;normalizedQuery:string;editingLevels:boolean;levelDrafts:Record<number,number>;setLevel:(employeeId:number,level:number)=>void}){
  const children=departments.filter(item=>Number(item.parent_id)===Number(department.id));
  const displayLevel=(employee:Record<string,any>)=>editingLevels?(levelDrafts[Number(employee.id)]??Number(employee.organizational_level??1)):Number(employee.organizational_level??1);
  const members=employees.filter(employee=>Number(employee.department_id)===Number(department.id)).sort((a,b)=>displayLevel(a)-displayLevel(b)||String(rtl?a.name_ar:a.name_en).localeCompare(String(rtl?b.name_ar:b.name_en),rtl?"ar":"en"));
  const manager=members.find(member=>Number(member.id)===Number(department.manager_employee_id))||members.find(member=>Number(member.organizational_level)===0);
  const jobById=new Map(jobs.map(job=>[Number(job.id),job]));
  const childMatches=(child:Record<string,any>):boolean=>{const childMembers=employees.filter(employee=>Number(employee.department_id)===Number(child.id));const text=`${child.name_en} ${child.name_ar} ${childMembers.map(member=>`${member.name_en} ${member.name_ar}`).join(" ")}`.toLocaleLowerCase();return !normalizedQuery||text.includes(normalizedQuery)||departments.filter(item=>Number(item.parent_id)===Number(child.id)).some(childMatches);};
  const visibleChildren=children.filter(childMatches);
  const nonManagerMembers=members.filter(member=>Number(member.id)!==Number(manager?.id));
  const visibleMembers=normalizedQuery?nonManagerMembers.filter(member=>`${member.name_en} ${member.name_ar} ${member.job_title_name}`.toLocaleLowerCase().includes(normalizedQuery)):nonManagerMembers;
  return <section className={`org-tree-node depth-${depth} ${tone}`}><div className="org-tree-heading"><div className="org-tree-department"><span className={`department-icon ${tone}`}><Building2/></span><div><small>{depth===0?(rtl?"قطاع رئيسي":"MAIN DIVISION"):(rtl?"إدارة تابعة":"DEPARTMENT")}</small><h3>{rtl?department.name_ar:department.name_en}</h3><p>{rtl?department.name_en:department.name_ar}</p></div><b>{formatNumber(members.length,rtl)}<small>{rtl?"موظف":"people"}</small></b></div>{manager&&<div className="org-tree-manager"><span className="org-level-number manager">{formatNumber(0,rtl)}</span><Avatar initials={personInitials(manager.name_en)} small tone={tone}/><span><small>{rtl?"مدير القسم":"DEPARTMENT MANAGER"}</small><b>{rtl?manager.name_ar:manager.name_en}</b></span></div>}</div>{visibleMembers.length>0&&<div className="org-tree-employees">{visibleMembers.map(member=>{const job=jobById.get(Number(member.job_title_id));const level=displayLevel(member);return <div className="org-tree-employee" key={member.id}>{editingLevels?<input className="org-level-input" type="number" min="1" max="20" value={level} aria-label={`${rtl?"مستوى":"Level"} ${rtl?member.name_ar:member.name_en}`} onChange={event=>setLevel(Number(member.id),Number(event.target.value))}/>:<span className="org-level-number">{formatNumber(level,rtl)}</span>}<Avatar initials={personInitials(member.name_en)} small tone={tone}/><div><b>{rtl?member.name_ar:member.name_en}</b><small>{rtl?(job?.name_ar||member.job_title_name):(job?.name_en||member.job_title_name)}</small></div></div>})}</div>}{visibleChildren.length>0&&<div className="org-tree-children">{visibleChildren.map(child=><OrgDepartmentTreeNode key={child.id} rtl={rtl} department={child} departments={departments} employees={employees} jobs={jobs} tone={tone} depth={depth+1} normalizedQuery={normalizedQuery} editingLevels={editingLevels} levelDrafts={levelDrafts} setLevel={setLevel}/>)}</div>}</section>
}

function UsersPage({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){const [tab,setTab]=useState("users");return <><PageHeader eyebrow={rtl?"إدارة الوصول":"ACCESS CONTROL"} title={rtl?"المستخدمون والصلاحيات":"Users & permissions"} text={rtl?"تحكم دقيق بالوصول بناءً على الدور ونطاق البيانات.":"Granular role-based access with clear data scope."} action={<button className="primary" onClick={()=>notify(rtl?"يُنشأ حساب المستخدم تلقائياً عند إضافة موظف جديد":"A user account is created automatically when you add an employee")}><Plus size={17}/>{rtl?"إضافة مستخدم":"Add user"}</button>}/><Tabs items={[{id:"users",label:rtl?"المستخدمون":"Users"},{id:"roles",label:rtl?"الأدوار والصلاحيات":"Roles & permissions"}]} active={tab} setActive={setTab}/>{tab==="users"?<div className="panel table-panel"><FilterBar rtl={rtl}/><EmployeeTable rtl={rtl} users/></div>:<PermissionEditor rtl={rtl} notify={notify}/>}</>}

function SettingsPage({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){const [selected,setSelected]=useState<{key:string;t:string;d:string}|null>(null);const {data,error,reload}=useHRData(rtl);const items=rtl?[{key:"company",i:Building2,t:"بيانات المنشأة",d:"الكيانات القانونية وقطاعات الأعمال والفروع"},{key:"schedules",i:Clock3,t:"الجداول والورديات",d:"أيام العمل وفترات السماح وأنماط الورديات"},{key:"attendance",i:Activity,t:"سياسات الحضور",d:"العمل الإضافي والتأخير وطلبات التصحيح"},{key:"leave",i:CalendarDays,t:"سياسات الإجازات",d:"الاستحقاقات وترحيل الرصيد ومسارات الاعتماد"},{key:"approvals",i:CheckCircle2,t:"مسارات الاعتماد",d:"تحديد مراحل الاعتماد حسب نوع الطلب"},{key:"notifications",i:Bell,t:"الإشعارات",d:"القنوات والقوالب والفئات المستهدفة"},{key:"locale",i:Globe2,t:"اللغات والمناطق",d:"العربية والإنجليزية والمناطق الزمنية والتنسيقات"},{key:"security",i:ShieldCheck,t:"الأمان",d:"الجلسات وكلمات المرور وسجل التدقيق"}]:[{key:"company",i:Building2,t:"Company information",d:"Legal entities, business units and offices"},{key:"schedules",i:Clock3,t:"Schedules & shifts",d:"Working days, grace periods and shift patterns"},{key:"attendance",i:Activity,t:"Attendance policies",d:"Overtime, lateness and correction rules"},{key:"leave",i:CalendarDays,t:"Leave policies",d:"Entitlements, carry-forward and approvals"},{key:"approvals",i:CheckCircle2,t:"Approval workflows",d:"Configure stages by request type"},{key:"notifications",i:Bell,t:"Notifications",d:"Channels, templates and audience rules"},{key:"locale",i:Globe2,t:"Languages & regions",d:"Arabic, English, time zones and formats"},{key:"security",i:ShieldCheck,t:"Security",d:"Sessions, passwords and audit controls"}];const initial=selected?parseSetting(data?.settings?.find(row=>row.setting_key===selected.key)):{};return <><PageHeader eyebrow={rtl?"إعداد النظام":"SYSTEM CONFIGURATION"} title={rtl?"الإعدادات":"Settings"} text={rtl?"خصّص إعدادات المنشأة والسياسات بما يناسب آلية العمل.":"Configure company settings and policies to match how your organization works."}/>{error&&<div className="error-banner">{error}<button onClick={()=>void reload()}>{rtl?"إعادة المحاولة":"Retry"}</button></div>}<div className="settings-grid wide">{items.map(({key,i:Icon,t,d},idx)=><button className="panel setting-card setting-button directional" key={key} onClick={()=>setSelected({key,t,d})}><span className={`setting-icon ${["blue","violet","green","amber"][idx%4]}`}><Icon/></span><div><h3>{t}</h3><p>{d}</p></div><ChevronRight/></button>)}</div>{selected&&<SettingsDrawer rtl={rtl} section={selected.key} title={selected.t} description={selected.d} initial={initial} close={()=>setSelected(null)} submit={async values=>{await hrApi({action:"save_system_settings",settingKey:selected.key,values});await reload();setSelected(null);notify(rtl?"تم حفظ الإعدادات بنجاح":"Settings saved successfully");}}/>}</>}

function PageHeader({eyebrow,title,text,action}:{eyebrow:string;title:string;text:string;action?:React.ReactNode}){return <section className="page-heading compact"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>{action}</section>}
function Tabs({items,active,setActive}:{items:{id:string;label:string}[];active:string;setActive:(s:string)=>void}){return <div className="tabs">{items.map(x=><button className={active===x.id?"active":""} key={x.id} onClick={()=>setActive(x.id)}>{x.label}</button>)}</div>}
function FilterBar({rtl}:{rtl:boolean}){const [query,setQuery]=useState("");const [filtersOpen,setFiltersOpen]=useState(false);const [department,setDepartment]=useState("all");const [period,setPeriod]=useState("month");const [grid,setGrid]=useState(false);const activeCount=(department==="all"?0:1)+(period==="all"?0:1);return <div className={`filterbar ${filtersOpen?"filters-open":""} ${grid?"grid-view":""}`}><label><Search size={17}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={rtl?"البحث...":"Search..."}/>{query&&<button className="filter-clear" onClick={()=>setQuery("")} aria-label={rtl?"مسح البحث":"Clear search"}><X size={14}/></button>}</label><button className={filtersOpen?"active":""} onClick={()=>setFiltersOpen(value=>!value)} aria-expanded={filtersOpen}><SlidersHorizontal size={16}/>{rtl?"التصفية":"Filters"}{activeCount>0&&<span className="filter-count">{formatNumber(activeCount,rtl)}</span>}</button><label className="desktop-filter"><select aria-label={rtl?"تصفية حسب القسم":"Filter by department"} value={department} onChange={event=>setDepartment(event.target.value)}><option value="all">{rtl?"كل الأقسام":"All departments"}</option><option value="people">{rtl?"الموارد البشرية":"People & Culture"}</option><option value="operations">{rtl?"العمليات":"Operations"}</option><option value="technology">{rtl?"التقنية":"Technology"}</option></select><ChevronDown size={14}/></label><label className="desktop-filter"><select aria-label={rtl?"تصفية حسب الفترة":"Filter by period"} value={period} onChange={event=>setPeriod(event.target.value)}><option value="month">{rtl?"هذا الشهر":"This month"}</option><option value="week">{rtl?"هذا الأسبوع":"This week"}</option><option value="all">{rtl?"كل الفترات":"All time"}</option></select><ChevronDown size={14}/></label><span className="spacer"/><button className={`icon-only ${grid?"active":""}`} onClick={()=>setGrid(value=>!value)} aria-pressed={grid} aria-label={rtl?"تبديل طريقة العرض":"Toggle view"}><Grid2X2 size={17}/></button></div>}

function RequestTable({rtl,rows=[]}:{rtl:boolean;rows?:Record<string,any>[]}){const [selected,setSelected]=useState<number|null>(null);if(!rows.length)return <Empty title={rtl?"لا توجد طلبات":"No requests"} text={rtl?"لم يتم تقديم أي طلبات حتى الآن.":"No requests have been submitted yet."}/>;return <div className="data-table"><div className="tr th"><span>{rtl?"نوع الطلب":"Request"}</span><span>{rtl?"تاريخ التقديم":"Submitted"}</span><span>{rtl?"الفترة أو القيمة":"Period / value"}</span><span>{rtl?"مرحلة الاعتماد":"Approval stage"}</span><span>{rtl?"الحالة":"Status"}</span><span></span></div>{rows.map(r=>{const id=Number(r.id);const period=r.amount?new Intl.NumberFormat(localeFor(rtl),{style:"currency",currency:String(r.currency||"SAR"),maximumFractionDigits:2}).format(Number(r.amount)):r.from_date&&r.to_date?`${formatDate(r.from_date,rtl,{day:"numeric",month:"short"})} — ${formatDate(r.to_date,rtl,{day:"numeric",month:"short"})}`:"—";return <div className={`tr ${selected===id?"selected":""}`} key={id}><span><b>{localizedRequestType(r.type,rtl)}</b><small>{r.request_code}</small></span><span>{r.created_at?formatDate(String(r.created_at).slice(0,10),rtl,{day:"numeric",month:"short",year:"numeric"}):"—"}</span><span>{period}</span><span>{localizedStage(r.current_stage,rtl)}</span><span><Status tone={String(r.status).includes("approved")?"green":String(r.status).includes("rejected")?"rose":"amber"}>{localizedStatus(r.status,rtl)}</Status></span><span><button className="plain-icon" onClick={()=>setSelected(current=>current===id?null:id)} aria-expanded={selected===id} aria-label={rtl?"عرض تفاصيل الطلب":"View request details"}><MoreHorizontal size={18}/></button></span></div>})}</div>}
function EmployeeTable({rtl,users=false,rows,onSelect}:{rtl:boolean;users?:boolean;rows?:Record<string,any>[];onSelect?:(employee:Record<string,any>)=>void}){const list=(rows??[]).map((e,i)=>({raw:e,name:e.name_en||e.employee_name||e.email,ar:e.name_ar||e.employee_name||e.email,initials:personInitials(e.name_en||e.employee_name||e.email),id:e.employee_code||e.email,dept:e.department_name||"—",deptAr:e.department_name_ar||e.department_name||"—",role:e.job_title_name||e.role_name||"—",roleAr:e.job_title_name_ar||e.role_name||"—",location:e.work_location||e.country||"—",locationAr:e.work_location_ar||localizedCountry(e.country,true)||"—",status:String(e.employment_status||e.status||"active").replaceAll("_"," "),tone:["violet","blue","rose","amber"][i%4]}));if(!list.length)return <Empty icon={Users} title={users?(rtl?"لا يوجد مستخدمون":"No users"):(rtl?"لا يوجد موظفون":"No employees")} text={users?(rtl?"لم تتم إضافة أي حسابات مستخدمين بعد.":"No user accounts have been added yet."):(rtl?"لم تتم إضافة أي موظفين بعد.":"No employees have been added yet.")}/>;return <div className="data-table employee-table"><div className="tr th"><span>{rtl?"الموظف":"Employee"}</span><span>{rtl?"القسم":"Department"}</span><span>{rtl?"المسمى الوظيفي":"Job title"}</span><span>{users?(rtl?"الدور والصلاحية":"Role"):(rtl?"موقع العمل":"Location")}</span><span>{rtl?"الحالة":"Status"}</span><span></span></div>{list.map((e:any)=><div className={`tr ${onSelect?"employee-row-clickable":""}`} key={e.id} role={onSelect?"button":undefined} tabIndex={onSelect?0:undefined} onClick={()=>onSelect?.(e.raw)} onKeyDown={event=>{if(onSelect&&(event.key==="Enter"||event.key===" ")){event.preventDefault();onSelect(e.raw);}}}><span className="person"><Avatar initials={e.initials} small tone={e.tone}/><span><b>{rtl?e.ar:e.name}</b><small>{e.id}</small></span></span><span>{rtl?e.deptAr:e.dept}</span><span>{rtl?e.roleAr:e.role}</span><span>{users?e.role:(rtl?e.locationAr:e.location)}</span><span><Status tone={String(e.status).toLowerCase()==="active"?"green":String(e.status).toLowerCase()==="on leave"?"violet":"amber"}>{localizedStatus(e.status,rtl)}</Status></span><span><button className="plain-icon" aria-label={rtl?"فتح ملف الموظف":"Open employee profile"} onClick={event=>{event.stopPropagation();onSelect?.(e.raw);}}><ChevronRight size={18}/></button></span></div>)}</div>}

function JobTitleTable({rtl,rows,departments,onEdit}:{rtl:boolean;rows?:Record<string,any>[];departments?:Record<string,any>[];onEdit:(job:Record<string,any>)=>void}){const list=rows??[];const departmentById=new Map((departments??[]).map(department=>[Number(department.id),department]));return list.length?<div className="data-table job-title-table"><div className="tr th"><span>{rtl?"الاسم بالإنجليزية":"English name"}</span><span>{rtl?"الاسم بالعربية":"Arabic name"}</span><span>{rtl?"القسم":"Department"}</span><span>{rtl?"عدد الموظفين":"Employees"}</span><span>{rtl?"الحالة":"Status"}</span><span></span></div>{list.map(job=>{const department=departmentById.get(Number(job.department_id));return <div className="tr" key={job.id}><span><b>{job.name_en}</b></span><span>{job.name_ar}</span><span>{rtl?(department?.name_ar||job.department_name):(department?.name_en||job.department_name)||"—"}</span><span>{formatNumber(Number(job.employee_count)||0,rtl)}</span><span><Status tone={job.status==="active"?"green":"gray"}>{localizedStatus(job.status||"active",rtl)}</Status></span><span><button className="plain-icon" onClick={()=>onEdit(job)} aria-label={rtl?`تعديل ${job.name_ar}`:`Edit ${job.name_en}`}><MoreHorizontal size={18}/></button></span></div>})}</div>:<Empty icon={BriefcaseBusiness} title={rtl?"لا توجد مسميات وظيفية":"No job titles"} text={rtl?"لم تُضف أي مسميات وظيفية حتى الآن.":"No job titles have been added yet."}/>} 
function DepartmentGrid({rtl,rows,jobs,employees,notify,reload,onEdit}:{rtl:boolean;rows?:Record<string,any>[];jobs?:Record<string,any>[];employees?:Record<string,any>[];notify:(s:string)=>void;reload:()=>Promise<void>;onEdit:(department:Record<string,any>)=>void}){
  const list=rows??[];const [selected,setSelected]=useState<Record<string,any>|null>(null);
  return <>{list.length?<div className="department-grid">{list.map((department,index)=>{const tone=["blue","violet","green","rose","amber"][index%5];const titleCount=(jobs??[]).filter(job=>Number(job.department_id)===Number(department.id)).length;return <article className="department-card" key={department.id}><span className={`department-icon ${tone}`}><Building2/></span><button className="department-edit" onClick={()=>onEdit(department)} aria-label={rtl?`تعديل ${department.name_ar}`:`Edit ${department.name_en}`}><MoreHorizontal size={18}/></button><h3>{rtl?department.name_ar:department.name_en}</h3><p>{rtl?department.name_en:department.name_ar}</p><div className="department-manager"><small>{rtl?"مدير القسم":"DEPARTMENT MANAGER"}</small><b>{rtl?(department.manager_name_ar||department.manager_name||"غير محدد"):(department.manager_name||"Not assigned")}</b></div><div className="department-summary"><BriefcaseBusiness size={17}/><span><small>{rtl?"المسميات الوظيفية":"Job titles"}</small><b>{formatNumber(titleCount,rtl)}</b></span></div><footer><Users size={15}/>{formatNumber(Number(department.employee_count)||0,rtl)} {rtl?"موظفاً":"employees"}<button className="department-open-button directional" onClick={()=>setSelected(department)}>{rtl?"فتح القسم":"Open department"}<ChevronRight size={14}/></button></footer></article>})}</div>:<Empty icon={Building2} title={rtl?"لا توجد أقسام":"No departments"} text={rtl?"لم يتم تحميل الأقسام بعد.":"Departments have not loaded yet."}/>} {selected&&<DepartmentHierarchyDrawer rtl={rtl} department={selected} employees={employees??[]} jobs={jobs??[]} close={()=>setSelected(null)} save={async(managerEmployeeId,assignments)=>{await hrApi({action:"save_department_hierarchy",departmentId:selected.id,managerEmployeeId,assignments});await reload();setSelected(null);notify(rtl?"تم حفظ مدير القسم والمستويات التنظيمية":"Department manager and organization levels saved");}}/>}</>
}

function DepartmentHierarchyDrawer({rtl,department,employees,jobs,close,save}:{rtl:boolean;department:Record<string,any>;employees:Record<string,any>[];jobs:Record<string,any>[];close:()=>void;save:(managerEmployeeId:number,assignments:{employeeId:number;managerId:number|null}[])=>Promise<void>}){
  const team=employees.filter(employee=>Number(employee.department_id)===Number(department.id));
  const initialManager=Number(department.manager_employee_id)||Number(team.find(employee=>Number(employee.organizational_level)===0)?.id)||Number(team[0]?.id)||0;
  const [managerId,setManagerId]=useState(initialManager);
  const [reports,setReports]=useState<Record<number,number|null>>(()=>Object.fromEntries(team.map(employee=>[Number(employee.id),Number(employee.manager_id)||null])));
  const [saving,setSaving]=useState(false); const [error,setError]=useState("");
  const jobById=new Map(jobs.map(job=>[Number(job.id),job]));
  const levels=useMemo(()=>{const result:Record<number,number>={};const walk=(id:number,path:Set<number>):number=>{if(id===managerId)return 0;if(result[id]!==undefined)return result[id];if(path.has(id))return 99;const next=new Set(path);next.add(id);const parent=reports[id]||managerId;return result[id]=parent===id?99:walk(parent,next)+1;};team.forEach(employee=>{result[Number(employee.id)]=walk(Number(employee.id),new Set());});return result;},[managerId,reports,team]);
  const ordered=[...team].sort((a,b)=>(levels[Number(a.id)]??99)-(levels[Number(b.id)]??99)||String(rtl?a.name_ar:a.name_en).localeCompare(String(rtl?b.name_ar:b.name_en),rtl?"ar":"en"));
  const changeManager=(id:number)=>{const previous=managerId;setManagerId(id);setReports(current=>{const next={...current,[id]:null};if(previous&&previous!==id)next[previous]=id;return next;});};
  const submit=async()=>{try{setSaving(true);setError("");await save(managerId,team.map(employee=>({employeeId:Number(employee.id),managerId:Number(employee.id)===managerId?null:(reports[Number(employee.id)]||managerId)})));}catch(reason){setError(reason instanceof Error?reason.message:(rtl?"تعذر حفظ الهيكل":"Unable to save structure"));setSaving(false);}};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق":"Close"}/><aside className="drawer department-drawer"><div className="drawer-head"><div><span className="eyebrow">{rtl?"إدارة القسم":"DEPARTMENT STRUCTURE"}</span><h2>{rtl?department.name_ar:department.name_en}</h2><p>{rtl?"حدد مدير القسم والمدير المباشر لكل موظف؛ وسيُحسب الرقم التنظيمي تلقائياً.":"Choose the department manager and each reporting line; organization numbers are calculated automatically."}</p></div><button className="icon-btn" onClick={close}><X size={20}/></button></div><div className="form-body department-structure-body">{error&&<div className="error-banner">{error}</div>}{team.length?<><label className="field manager-field"><span>{rtl?"مدير القسم · ٠":"Department manager · 0"}</span><select value={managerId} onChange={event=>changeManager(Number(event.target.value))}>{team.map(employee=><option value={employee.id} key={employee.id}>{rtl?employee.name_ar:employee.name_en}</option>)}</select></label><div className="hierarchy-key"><span><b>0</b>{rtl?"مدير القسم":"Department manager"}</span><i/><span><b>1+</b>{rtl?"الفريق":"Team"}</span></div><div className="hierarchy-list">{ordered.map((employee,index)=>{const level=levels[Number(employee.id)]??1;const job=jobById.get(Number(employee.job_title_id));const isManager=Number(employee.id)===managerId;return <div className="hierarchy-row" key={employee.id} style={{"--org-level":Math.min(level,5)} as React.CSSProperties}><span className={`level-badge ${isManager?"manager":""}`}>{formatNumber(level,rtl)}</span><Avatar initials={personInitials(employee.name_en)} small tone={["blue","violet","green","amber"][index%4]}/><div className="hierarchy-person"><b>{rtl?employee.name_ar:employee.name_en}</b><small>{rtl?(job?.name_ar||employee.job_title_name):(job?.name_en||employee.job_title_name)||"—"}</small></div>{isManager?<Status tone="blue">{rtl?"مدير القسم":"Manager"}</Status>:<label><small>{rtl?"المدير المباشر":"Reports to"}</small><select value={reports[Number(employee.id)]||managerId} onChange={event=>setReports(current=>({...current,[Number(employee.id)]:Number(event.target.value)}))}>{team.filter(option=>Number(option.id)!==Number(employee.id)).map(option=><option value={option.id} key={option.id}>{rtl?option.name_ar:option.name_en}</option>)}</select></label>}</div>})}</div></>:<Empty icon={Users} title={rtl?"لا يوجد موظفون في هذا القسم":"No employees in this department"} text={rtl?"أضف موظفاً للقسم أولاً لتحديد المدير والأرقام التنظيمية.":"Add an employee before configuring its manager and organization numbers."}/>}</div><div className="drawer-footer"><span/><button className="outline" onClick={close}>{rtl?"إلغاء":"Cancel"}</button><button className="primary" disabled={!team.length||saving} onClick={()=>void submit()}><Check size={16}/>{saving?(rtl?"جارٍ الحفظ...":"Saving..."):(rtl?"حفظ الهيكل":"Save structure")}</button></div></aside></div>
}
function HolidayCalendar({rtl,rows}:{rtl:boolean;rows?:Record<string,any>[]}){
  const list=(rows??[]).filter(h=>String(h.holiday_date||"").startsWith("2026-")).sort((a,b)=>String(a.holiday_date).localeCompare(String(b.holiday_date)));
  return <div className="panel official-holidays"><div className="official-holidays-head"><div><span className="eyebrow">{rtl?"التقويم السنوي":"ANNUAL CALENDAR"}</span><h2>{rtl?"قائمة الإجازات الرسمية 2026":"Official holidays 2026"}</h2><p>{rtl?`${formatNumber(list.length,rtl)} إجازة مسجلة لمصر والمملكة العربية السعودية`:`${list.length} holidays registered for Egypt and Saudi Arabia`}</p></div><span><CalendarDays size={18}/>{formatNumber(2026,rtl)}</span></div>
    {list.length?<div className="official-holiday-scroll"><div className="official-holiday-table"><div className="official-holiday-row head"><span>{rtl?"التاريخ":"Date"}</span><span>{rtl?"اسم الإجازة":"Holiday name"}</span><span>{rtl?"أنواع الحضور":"Attendance types"}</span><span>{rtl?"النوع":"Type"}</span><span>{rtl?"الإجراءات":"Actions"}</span></div>{list.map((holiday,index)=>{const attendance=String(holiday.attendance_types||"").split("|").filter(Boolean);return <div className="official-holiday-row" key={`${holiday.holiday_date}-${holiday.name_ar}-${holiday.id??index}`}><span className="official-date"><b>{formatDate(String(holiday.holiday_date),rtl,{day:"2-digit",month:"2-digit",year:"numeric"})}</b><small>{formatDate(String(holiday.holiday_date),rtl,{weekday:"long"})}</small></span><span className="official-name"><b>{rtl?holiday.name_ar:holiday.name_en}</b><small>{localizedCountry(holiday.country,rtl)}</small></span><span className="attendance-chips">{attendance.length?attendance.map((type:string)=><i key={type}>{type}</i>):<i>{rtl?"غير محدد":"Not specified"}</i>}</span><span><Status tone={holiday.recurrence_type==="annual"?"blue":"gray"}>{holiday.recurrence_type==="annual"?(rtl?"سنوي":"Annual"):(rtl?"لمرة واحدة":"One time")}</Status></span><span><button className="plain-icon" aria-label={rtl?"إجراءات الإجازة":"Holiday actions"}><MoreHorizontal size={18}/></button></span></div>})}</div></div>:<Empty icon={CalendarDays} title={rtl?"لا توجد إجازات في 2026":"No holidays in 2026"} text={rtl?"أضف أول إجازة رسمية لهذا العام.":"Add the first official holiday for this year."}/>}</div>
}

function AttendanceTable({rtl,logs}:{rtl:boolean;logs:boolean}){const [selected,setSelected]=useState<string|null>(null);return <div className="data-table attendance-table"><div className="tr th"><span>{rtl?"الموظف":"Employee"}</span><span>{rtl?"التاريخ":"Date"}</span><span>{logs?(rtl?"الوقت والحدث":"Time / event"):(rtl?"الدوام المقرر":"Scheduled")}</span><span>{logs?(rtl?"مصدر التسجيل":"Source"):(rtl?"الدوام الفعلي":"Actual")}</span><span>{logs?(rtl?"الجهاز":"Device"):(rtl?"المدة المسجلة":"Worked")}</span><span>{rtl?"الحالة":"Status"}</span><span></span></div>{employees.map((e,i)=>{const open=selected===e.id;return <div className={`tr ${open?"selected":""}`} key={e.id}><span className="person"><Avatar initials={e.initials} small tone={e.tone}/><span><b>{rtl?e.ar:e.name}</b><small>{e.id}{open&&` · ${rtl?"تم فتح السجل":"Record opened"}`}</small></span></span><span>{formatDate("2026-08-14",rtl)}</span><span>{logs?`${formatTime(i%2?"08:59":"08:54",rtl)} · ${rtl?"تسجيل حضور":"Check-in"}`:`${formatTime("09:00",rtl)} — ${formatTime("17:00",rtl)}`}</span><span>{logs?(i===1?(rtl?"عن بُعد":"Remote"):(rtl?"جهاز البصمة":"Fingerprint")):i===2?(rtl?"في إجازة":"On leave"):`${formatTime("08:57",rtl)} — ${formatTime("17:12",rtl)}`}</span><span>{logs?(i===1?(rtl?"بوابة الحضور عن بُعد":"Remote web"):"ZK-Office-01"):i===2?"—":(rtl?"٨ ساعات و١٥ دقيقة":"8 hr 15 min")}</span><span><Status tone={i===2?"violet":i===3?"amber":"green"}>{localizedStatus(i===2?"leave":i===3?"late":"present",rtl)}</Status></span><span><button className="plain-icon" onClick={()=>setSelected(current=>current===e.id?null:e.id)} aria-expanded={open} aria-label={rtl?"عرض تفاصيل السجل":"View record details"}><MoreHorizontal size={18}/></button></span></div>})}</div>}
function PermissionEditor({rtl,notify}:{rtl:boolean;notify:(s:string)=>void}){
  const modules=rtl?["الموظفون","الحضور والانصراف","إدارة الإجازات","الطلبات","الرواتب","المستخدمون والصلاحيات"]:["Employees","Attendance","Leave management","Requests","Payroll","Users & permissions"];
  const [roleNames,setRoleNames]=useState(rtl?["مدير النظام","مدير الموارد البشرية","أخصائي موارد بشرية","المدير المباشر","موظف"]:["Super Admin","HR Manager","HR Specialist","Direct Manager","Employee"]);const [selectedRole,setSelectedRole]=useState(2);
  const permissions=rtl?["عرض","إنشاء","تعديل","حذف","اعتماد","تصدير"]:["View","Create","Edit","Delete","Approve","Export"];
  const addRole=()=>{const name=rtl?`دور مخصص ${formatNumber(roleNames.length-4,rtl)}`:`Custom role ${roleNames.length-4}`;setRoleNames(current=>[...current,name]);setSelectedRole(roleNames.length);notify(rtl?"تمت إضافة دور جديد؛ عدّل صلاحياته ثم احفظ":"A new role was added; configure its permissions and save")};
  return <div className="permission-layout"><aside className="panel role-list"><div className="panel-head"><h2>{rtl?"الأدوار الوظيفية":"Roles"}</h2><button onClick={addRole} aria-label={rtl?"إضافة دور":"Add role"}><Plus size={16}/></button></div>{roleNames.map((roleName,i)=><button className={`${i===selectedRole?"active":""} directional`} key={roleName} onClick={()=>setSelectedRole(i)}><span className={`role-symbol ${["navy","violet","blue","green","gray"][i%5]}`}><ShieldCheck size={17}/></span><span><b>{roleName}</b><small>{formatNumber([1,3,5,18,99,0][i]??0,rtl)} {rtl?"مستخدم":"users"}</small></span><ChevronRight size={15}/></button>)}</aside><div className="panel permissions"><div className="panel-head"><div><h2>{roleNames[selectedRole]}</h2><p>{rtl?"صلاحيات تشغيل عمليات الموارد البشرية":"Operational HR access"}</p></div><button className="primary" onClick={()=>notify(rtl?`تم حفظ صلاحيات ${roleNames[selectedRole]} بنجاح`:`Permissions for ${roleNames[selectedRole]} saved`)}><Check size={16}/>{rtl?"حفظ التغييرات":"Save changes"}</button></div><div className="permission-table"><div className="permission-row head"><span>{rtl?"الوحدة":"Module"}</span>{permissions.map(x=><span key={x}>{x}</span>)}</div>{modules.map((m,i)=><div className="permission-row" key={`${selectedRole}-${m}`}><b>{m}</b>{Array.from({length:6},(_,j)=><label className="check-control" key={j}><input type="checkbox" aria-label={`${m} — ${permissions[j]}`} defaultChecked={selectedRole===2&&((i<4&&j<3)||(i===1&&j===5)||(i===3&&j===4))}/><span><Check size={12}/></span></label>)}</div>)}</div></div></div>
}

function RequestDrawer({rtl,close,submit}:{rtl:boolean;close:()=>void;submit:(payload:Record<string,unknown>)=>Promise<void>}){
  const [form,setForm]=useState({type:"Annual leave",fromDate:"2026-08-18",toDate:"2026-08-21",requestDate:"2026-08-14",amount:"",reason:"",notes:""});const [attachment,setAttachment]=useState("");const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const hasDuration=useMemo(()=>form.type.toLowerCase().includes("leave"),[form.type]);const types=["Annual leave","Sick leave","Late arrival","Early departure","Work from home","Expense reimbursement","Experience certificate"];
  const update=(key:string,value:string)=>setForm(current=>({...current,[key]:value}));
  const send=async()=>{const reason=form.reason.trim();if(!reason){setError(rtl?"اكتب سبب الطلب قبل الإرسال":"Add a reason before submitting");return;}if(form.type==="Expense reimbursement"&&!Number(form.amount)){setError(rtl?"أدخل قيمة المصروف":"Enter the expense amount");return;}try{setSaving(true);setError("");await submit({type:form.type,fromDate:form.type==="Expense reimbursement"?null:form.fromDate,toDate:form.type==="Expense reimbursement"?null:form.toDate,requestDate:form.type==="Expense reimbursement"?form.requestDate:null,amount:form.type==="Expense reimbursement"?Number(form.amount):null,currency:form.type==="Expense reimbursement"?"SAR":null,reason,notes:form.notes,details:{attachmentName:attachment||null}})}catch(reasonValue){setError(reasonValue instanceof Error?reasonValue.message:(rtl?"تعذر إرسال الطلب":"Unable to submit request"));setSaving(false)}};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق النافذة":"Close"}/><aside className="drawer"><div className="drawer-head"><div><span className="eyebrow">{rtl?"الخدمة الذاتية للموظف":"EMPLOYEE SERVICE"}</span><h2>{rtl?"تقديم طلب جديد":"Create a new request"}</h2><p>{rtl?"سيصل الطلب إلى مديرك المباشر للمراجعة أولاً.":"Your direct manager will review the request first."}</p></div><button className="icon-btn" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></div><div className="form-progress"><span className="active"><b>{formatNumber(1,rtl)}</b>{rtl?"بيانات الطلب":"Details"}</span><i/><span><b>{formatNumber(2,rtl)}</b>{rtl?"المراجعة والإرسال":"Review"}</span></div><div className="form-body">{error&&<div className="form-error" role="alert">{error}</div>}<label className="field"><span>{rtl?"نوع الطلب":"Request type"}</span><select value={form.type} onChange={event=>update("type",event.target.value)}>{types.map(value=><option value={value} key={value}>{localizedRequestType(value,rtl)}</option>)}</select></label>{form.type==="Expense reimbursement"?<><div className="form-row"><label className="field"><span>{rtl?"تاريخ المصروف":"Expense date"}</span><input type="date" value={form.requestDate} onChange={event=>update("requestDate",event.target.value)}/></label><label className="field"><span>{rtl?"المبلغ بالريال":"Amount (SAR)"}</span><input inputMode="decimal" value={form.amount} onChange={event=>update("amount",event.target.value)} placeholder={rtl?"٠٫٠٠":"0.00"}/></label></div><label className="field"><span>{rtl?"تفاصيل المصروف":"Description"}</span><textarea value={form.reason} onChange={event=>update("reason",event.target.value)} placeholder={rtl?"وضّح تفاصيل المصروف وسبب المطالبة...":"Describe the expense and business purpose..."}/></label></>:<><div className="form-row"><label className="field"><span>{rtl?"تاريخ البداية":"From date"}</span><input type="date" value={form.fromDate} onChange={event=>update("fromDate",event.target.value)}/></label><label className="field"><span>{rtl?"تاريخ النهاية":"To date"}</span><input type="date" value={form.toDate} onChange={event=>update("toDate",event.target.value)}/></label></div>{hasDuration&&<div className="duration-note"><CalendarDays size={18}/><span><b>{rtl?"سيُحتسب عدد أيام العمل عند الإرسال":"Working days are calculated on submission"}</b><small>{rtl?"رصيدك المتاح: ١٨ يوماً":"Available balance: 18 days"}</small></span></div>}<label className="field"><span>{rtl?"سبب الطلب":"Reason"}</span><textarea value={form.reason} onChange={event=>update("reason",event.target.value)} placeholder={rtl?"اكتب سبباً واضحاً يساعد مديرك على المراجعة...":"Add a clear reason to help your manager review the request..."}/></label></>}<label className="upload"><input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={event=>setAttachment(event.target.files?.[0]?.name||"")}/><FileText size={21}/><span><b>{attachment|| (rtl?"إرفاق مستند":"Add attachment")}</b><small>{rtl?"PDF أو JPG أو PNG · بحد أقصى ١٠ م.ب":"PDF, JPG or PNG · Up to 10 MB"}</small></span><Plus size={17}/></label></div><div className="drawer-footer"><button className="ghost" onClick={close}>{rtl?"إغلاق والمتابعة لاحقاً":"Close and continue later"}</button><span/><button className="outline" onClick={close}>{rtl?"إلغاء":"Cancel"}</button><button className="primary directional" disabled={saving} onClick={()=>void send()}>{saving?(rtl?"جارٍ الإرسال...":"Submitting..."):(rtl?"إرسال الطلب":"Submit request")}<ChevronRight size={16}/></button></div></aside></div>
}
function Notifications({rtl,onClose,openPage}:{rtl:boolean;onClose:()=>void;openPage:(page:Page)=>void}){const items=rtl?[{i:CheckCircle2,t:"تم اعتماد طلب الإجازة",d:"اعتمد مديرك الطلب REQ-1048",c:"green",page:"portal" as Page},{i:Clock3,t:"تنبيه الحضور",d:"لديك جلسة عمل عن بُعد ما زالت نشطة",c:"blue",page:"portal" as Page},{i:Users,t:"طلب جديد بانتظار المراجعة",d:"قدّم عمر طلب عمل عن بُعد",c:"violet",page:"approvals" as Page}]:[{i:CheckCircle2,t:"Leave request approved",d:"Your manager approved REQ-1048",c:"green",page:"portal" as Page},{i:Clock3,t:"Attendance reminder",d:"You have an active remote session",c:"blue",page:"portal" as Page},{i:Users,t:"New request to review",d:"Omar submitted a remote-work request",c:"violet",page:"approvals" as Page}];const go=(page:Page)=>{openPage(page);onClose()};return <div className="notification-pop"><div className="panel-head"><div><h2>{rtl?"الإشعارات":"Notifications"}</h2><p>{rtl?`لديك ${formatNumber(3,rtl)} إشعارات جديدة`:"You have 3 new updates"}</p></div><button onClick={onClose} aria-label={rtl?"إغلاق الإشعارات":"Close notifications"}><X size={17}/></button></div>{items.map(({i:Icon,t,d,c,page})=><button className="notification-item" key={t} onClick={()=>go(page)}><span className={`notification-icon ${c}`}><Icon size={17}/></span><span><b>{t}</b><small>{d}</small></span><i/></button>)}<button className="view-notifications" onClick={()=>go("approvals")}>{rtl?"عرض جميع الإشعارات":"View all notifications"}</button></div>}
